import { Download } from "lucide-react";

interface CtaButtonProps {
  label?: string;
  href?: string;
}

export function CtaButton({ label = "Get Innovation Materials", href = "#" }: CtaButtonProps) {
  return (
    <div className="container mx-auto px-4 py-16">
      <a
        href={href}
        className="w-full max-w-2xl mx-auto flex bg-gradient-to-r from-[#033C5A] to-[#024D75] text-white py-8 px-12 rounded-2xl shadow-2xl transition-all relative overflow-hidden group"
      >
        <div className="absolute inset-0 bg-gradient-to-r from-[#AA9868] to-[#D4C5A0] opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        <div className="relative z-10 flex items-center justify-center gap-4 w-full">
          <Download className="w-8 h-8" />
          <span className="text-2xl">{label}</span>
        </div>
      </a>
    </div>
  );
}

interface HeroSectionProps {
  title: string;
  subtitle: string;
}

export function HeroSection({ title, subtitle }: HeroSectionProps) {
  return (
    <div className="relative py-20 md:py-18 -mb-16">
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-10 left-20 w-64 h-64 bg-white rounded-full blur-3xl"></div>
        <div className="absolute bottom-10 right-20 w-96 h-96 bg-white rounded-full blur-3xl"></div>
      </div>
      <div className="w-full container mx-auto px-4 text-center relative z-10">
        <h1 className="text-7xl md:text-8xl font-serif text-white mb-2 md:mb-4">{title}</h1>
        <p className="text-3xl md:text-4xl font-thin text-white/70">{subtitle}</p>
      </div>
    </div>
  );
}

import { ArrowRight } from "lucide-react";
import { Card } from "@/components/ui";
import type { HowToUseData } from "../types";

export function HowToUseSection({ steps }: HowToUseData) {
  return (
    <div className="py-20 max-w-3xl px-4">
      <div className="container mx-auto">
        <h2 className="text-5xl md:text-6xl font-serif text-white text-center mb-16">How do you use it?</h2>

        <div>
          <Card className="p-8 bg-white/10 backdrop-blur-sm shadow-2xl relative border-white/20">
            <div className="space-y-8">
              {steps.map((step, index) => (
                <div key={index}>
                  <div
                    className={`flex items-start gap-6 ${index % 2 === 0 ? "flex-row" : "flex-row-reverse"}`}
                  >
                    <div className="flex-shrink-0">
                      <div className="flex items-center gap-4">
                        <span className="text-2xl font-bold text-[#AA9868]">
                          {index + 1}.
                        </span>
                        <div className="bg-gray-300 w-20 h-20 rounded-lg flex items-center justify-center">
                          <step.icon className="w-10 h-10 text-white" />
                        </div>
                      </div>
                    </div>
                    <div
                      className={`flex-1 ${index % 2 === 0 ? "text-left" : "text-right"}`}
                    >
                      <h4 className="text-white mb-2">{step.title}</h4>
                      <p className="text-white/80">{step.description}</p>
                    </div>
                  </div>
                  {index < steps.length - 1 && (
                    <div
                      className={`flex ${index % 2 === 0 ? "justify-end" : "justify-start"} my-4`}
                    >
                      <ArrowRight
                        className="w-8 h-8 text-[#AA9868]"
                        style={{
                          transform:
                            index % 2 === 0
                              ? "rotate(90deg)"
                              : "rotate(90deg) scaleX(-1)",
                        }}
                      />
                    </div>
                  )}
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

"use client";

import { motion } from "motion/react";
import { ChevronLeft, ChevronRight } from "lucide-react";

interface NavigationFooterProps {
  prevHref?: string;
  nextHref?: string;
  current?: number;
  total?: number;
}

export function NavigationFooter({
  prevHref,
  nextHref,
  current = 1,
  total = 1,
}: NavigationFooterProps) {
  const dots = Array.from({ length: total }, (_, i) => i + 1);

  return (
    <div className="bg-[#5A6C7D] py-6 mt-20">
      <div className="container mx-auto px-4">
        <div className="flex justify-between items-center">
          <motion.a
            href={prevHref ?? "#"}
            whileHover={{ scale: 1.05, x: -5 }}
            whileTap={{ scale: 0.95 }}
            className={`flex items-center gap-2 text-white hover:text-[#AA9868] transition-colors ${!prevHref ? "opacity-30 pointer-events-none" : ""}`}
          >
            <ChevronLeft className="w-5 h-5" />
            <span>PREV</span>
          </motion.a>

          <div className="flex items-center gap-4">
            <span className="text-white text-sm">ALL INNOVATIONS</span>
            <div className="flex gap-2">
              {dots.map((dot) => (
                <motion.div
                  key={dot}
                  whileHover={{ scale: 1.3 }}
                  className={`w-2 h-2 rounded-full ${dot === current ? "bg-[#AA9868]" : "bg-white/50"} cursor-pointer`}
                />
              ))}
            </div>
          </div>

          <motion.a
            href={nextHref ?? "#"}
            whileHover={{ scale: 1.05, x: 5 }}
            whileTap={{ scale: 0.95 }}
            className={`flex items-center gap-2 text-white hover:text-[#AA9868] transition-colors ${!nextHref ? "opacity-30 pointer-events-none" : ""}`}
          >
            <span>NEXT</span>
            <ChevronRight className="w-5 h-5" />
          </motion.a>
        </div>
      </div>
    </div>
  );
}

import { HeroSection } from "./components/hero-section";
import { WhatIsItSection } from "./components/what-is-it-section";
import { HowToUseSection } from "./components/how-to-section";
import { TestingSection } from "./components/test-it-section";
import { UserStorySection } from "./components/user-story-section";
import { GetItSection } from "./components/get-it-section";
import { CtaButton } from "./components/cta-button";
import { NavigationFooter } from "./components/nav-footer";
import type { InnovationData } from "./types";

interface InnovationProps {
  data: InnovationData;
}

export function Innovation({ data }: InnovationProps) {
  return (
    <div className="min-h-screen bg-background">
      <div className="w-full flex flex-col items-center mx-auto">

        <HeroSection
          title={data.hero.title}
          subtitle={data.hero.subtitle}
        />

        <WhatIsItSection {...data.whatIsIt} />
        <HowToUseSection {...data.howToUse} />
        <TestingSection {...data.testing} />
        <UserStorySection {...data.userStory} />
        <GetItSection {...data.getIt} />

        <CtaButton
          label={data.cta?.label}
          href={data.cta?.href}
        />

        <NavigationFooter
          prevHref={data.navigation?.prevHref}
          nextHref={data.navigation?.nextHref}
          current={data.navigation?.current}
          total={data.navigation?.total}
        />
      </div>
    </div>
  );
}

import type { LucideIcon } from "lucide-react";

export interface WhatIsItData {
  headline: string;
  body: string;
  capabilities: { label: string; detail: string }[];
  highlight: string;
}

export interface HowToUseData {
  steps: {
    title: string;
    description: string;
    icon: LucideIcon;
  }[];
}

export interface TestingData {
  headline: string;
  body: string;
  callout: string;
  barData: { name: string; value: number }[];
  pieData1: { name: string; value: number }[];
  pieData2: { name: string; value: number }[];
}

export interface UserStoryData {
  storyIntro: string;
  paragraphs: string[];
  quote: string;
  name: string;
  role: string;
  org: string;
}

export interface GetItData {
  heading: string;
  body: string;
  resources: {
    icon: LucideIcon;
    label: string;
    href?: string;
  }[];
  highlight: string;
}

export interface InnovationData {
  hero: {
    title: string;
    subtitle: string;
  };
  whatIsIt: WhatIsItData;
  howToUse: HowToUseData;
  testing: TestingData;
  userStory: UserStoryData;
  getIt: GetItData;
  cta?: {
    label?: string;
    href?: string;
  };
  navigation?: {
    prevHref?: string;
    nextHref?: string;
    current?: number;
    total?: number;
  };
}
